#include "frodo_block_staged.h"
#include "frodo_block_mapping.h"
#include <string.h>
static int workspace_ok(const frodo_stage_workspace*w,size_t block){return w&&w->candidates&&w->signs&&block&&w->capacity>=block;}
static uint64_t mark(frodo_stage_timing*t){return t&&t->read?t->read(t->context):0;}
int frodo_sda_map_materialized(uint16_t*out,const uint16_t*c,const uint8_t*s,size_t n,const sdat_table*t){if(t==&sda_table_frodo640)return frodo640_sda_map_materialized(out,c,s,n);if(t==&sda_table_frodo976)return frodo976_sda_map_materialized(out,c,s,n);if(t==&sda_table_frodo1344)return frodo1344_sda_map_materialized(out,c,s,n);return -1;}
int frodo_original_block_staged_sample_n(uint16_t*out,size_t n,const uint16_t*words,size_t wc,const sdat_table*t,size_t block,frodo_stage_workspace*w,sdat_stats*st,frodo_stage_timing*tm){if(!out||!words||!t||!workspace_ok(w,block)||wc<n)return -1;if(st)*st=(sdat_stats){0};if(tm){tm->input_cycles=0;tm->mapping_cycles=0;}size_t done=0;while(done<n){size_t take=n-done<block?n-done:block;uint64_t t0=mark(tm);if(frodo_original_materialize_words(w->candidates,w->signs,take,words+done,wc-done)!=take)return -2;uint64_t t1=mark(tm);if(frodo_original_map_materialized(out+done,w->candidates,w->signs,take,t))return -3;uint64_t t2=mark(tm);if(tm&&tm->read){tm->input_cycles+=t1-t0;tm->mapping_cycles+=t2-t1;}done+=take;}if(st){st->attempts=n;st->random_bytes=n*2;st->random_bits=n*16;}return 0;}
int frodo_sda_block_staged_sample_n(uint16_t*out,size_t n,const uint16_t*words,size_t wc,const sdat_table*t,size_t block,frodo_stage_workspace*w,sdat_stats*st,frodo_stage_timing*tm){if(!out||!words||!t||!workspace_ok(w,block))return -1;if(st)*st=(sdat_stats){0};if(tm){tm->input_cycles=0;tm->mapping_cycles=0;}size_t done=0,pos=0;while(done<n){size_t take=n-done<block?n-done:block;uint64_t t0=mark(tm);size_t used=frodo_sda_materialize_words(w->candidates,w->signs,take,words+pos,wc-pos,t);if(!used)return -2;uint64_t t1=mark(tm);if(frodo_sda_map_materialized(out+done,w->candidates,w->signs,take,t))return -3;uint64_t t2=mark(tm);if(tm&&tm->read){tm->input_cycles+=t1-t0;tm->mapping_cycles+=t2-t1;}pos+=used;done+=take;}if(st){st->attempts=pos;st->rejections=pos-n;st->random_bytes=pos*2;st->random_bits=(uint64_t)t->random_draw_bits*pos+n;}return 0;}
